using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows.Forms;

namespace StyxHostUpdate {
 sealed class Updater:Form {
  readonly string root=AppDomain.CurrentDomain.BaseDirectory;readonly Label status;readonly ProgressBar progress;readonly Button reopen;bool working=true;string state;readonly bool rollback;readonly int ownerPid;
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer {MaxJsonLength=2097152};
  static string Field(object value,string key){var d=value as Dictionary<string,object>;object item;return d!=null&&d.TryGetValue(key,out item)?item as string??"":"";}
  static string Quote(string value){if(value.IndexOf('"')>=0||value.IndexOf('\n')>=0||value.IndexOf('\r')>=0)throw new IOException();return "\""+value+"\"";}
  static string Hash(string file){using(var h=System.Security.Cryptography.SHA256.Create())using(var f=File.OpenRead(file)){return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}}
  internal Updater(bool restore,int owner){rollback=restore;ownerPid=owner;Text="Styx Update";ClientSize=new Size(420,170);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);status=new Label {Text="Waiting for Styx to close…",Left=24,Top=24,Width=370,Height=65};progress=new ProgressBar {Left=24,Top=100,Width=370,Height=8,Style=ProgressBarStyle.Marquee};reopen=new Button {Text="Open Styx",Left=284,Top=125,Width=110,Visible=false};reopen.Click+=(s,e)=>OpenOriginal();Controls.Add(status);Controls.Add(progress);Controls.Add(reopen);FormClosing+=(s,e)=>{if(working)e.Cancel=true;};Shown+=async(s,e)=>await Run();}
  object Execute(string arguments){var info=new ProcessStartInfo(Path.Combine(root,"node.exe"),Quote(Path.Combine(root,"vnext","onboarding","cli.mjs"))+" "+arguments){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=root};info.EnvironmentVariables.Remove("NODE_OPTIONS");info.EnvironmentVariables.Remove("NODE_PATH");using(var child=new Process {StartInfo=info}){child.ErrorDataReceived+=(s,e)=>{};child.Start();child.BeginErrorReadLine();string output=child.StandardOutput.ReadToEnd();child.WaitForExit();if(output.Length>2097152||child.ExitCode!=0)throw new IOException();return Json.DeserializeObject(output);}}
  static bool DoctorReady(object health){var data=health as Dictionary<string,object>;object steps;if(data!=null&&data.TryGetValue("steps",out steps)){var items=steps as System.Collections.IEnumerable;if(items!=null)foreach(var item in items)if(Field(item,"id")=="host.doctor"&&Field(item,"status")=="succeeded")return true;}return false;}
  async Task Run(){try{var input=Json.DeserializeObject(File.ReadAllText(Path.Combine(root,"input.json")));state=Field(input,"stateDir");string ticket=Field(input,"ticketId");if(!Path.IsPathRooted(state)||!System.Text.RegularExpressions.Regex.IsMatch(ticket,"^[a-f0-9]{32}$"))throw new IOException();var until=DateTime.UtcNow.AddMinutes(2);object result;
    if(rollback){while(true){bool alive;try{using(var owner=Process.GetProcessById(ownerPid))alive=!owner.HasExited;}catch(ArgumentException){alive=false;}if(!alive)break;if(DateTime.UtcNow>until)throw new IOException();await Task.Delay(500);}
     status.Text="Restoring the previous components…";var journal=await Task.Run(()=>Execute("host-payload-status "+Quote(state)));string transaction=Field(journal,"transactionId");if(Field(journal,"handoffTicketId")!=ticket||!System.Text.RegularExpressions.Regex.IsMatch(transaction,"^[a-f0-9]{32}$"))throw new IOException();var restored=await Task.Run(()=>Execute("host-payload-rollback "+Quote(state)+" "+Quote(transaction)+" --authorize"));if(Field(restored,"status")!="rolled_back_stopped")throw new IOException();status.Text="Checking the restored components…";var restoredHealth=await Task.Run(()=>Execute("advance "+Quote(state)+" host.doctor"));if(!DoctorReady(restoredHealth)){working=false;progress.Visible=false;status.Text="Previous components restored. Open Styx to review the computer check.";reopen.Visible=true;return;}working=false;status.Text="Previous components restored. Reopening Styx…";OpenOriginal();return;
    }
    while(true){result=await Task.Run(()=>Execute("host-payload-handoff-execute "+Quote(state)+" "+Quote(ticket)+" --authorize"));if(Field(result,"status")!="waiting_for_exit")break;if(DateTime.UtcNow>until)throw new IOException();await Task.Delay(1000);status.Text="Waiting for Styx to finish closing…";}
    if(Field(result,"status")!="applied_stopped"){working=false;progress.Visible=false;status.Text="The update could not start. Your settings are retained. Open Styx to review the result.";reopen.Visible=true;return;}
    status.Text="Checking the updated components…";var health=await Task.Run(()=>Execute("advance "+Quote(state)+" host.doctor"));bool ready=DoctorReady(health);if(!ready){working=false;progress.Visible=false;status.Text="The components were updated, but the computer check needs attention. Open Styx to review it.";reopen.Visible=true;return;}
    string app=Field(result,"appPath");if(!Path.IsPathRooted(app)||Path.GetFileName(app)!="StyxPreview.exe"||Hash(app)!=Hash(Path.Combine(root,"StyxPreview.exe")))throw new IOException();status.Text="Updated. Reopening Styx…";working=false;StartApp(app);Close();
   }catch{working=false;progress.Visible=false;status.Text="The update needs review. Your recovery record is retained. Open Styx to review it before trying again.";reopen.Visible=true;}}
  void StartApp(string app){var info=new ProcessStartInfo(app){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(app)};info.EnvironmentVariables["STYX_NATIVE_STATE"]=Path.GetDirectoryName(state);info.EnvironmentVariables.Remove("NODE_OPTIONS");info.EnvironmentVariables.Remove("NODE_PATH");Process.Start(info);}
  void OpenOriginal(){try{var ticket=Json.DeserializeObject(File.ReadAllText(Path.Combine(state,"host-payload-handoff.json")));string app=Field(ticket,"appPath");if(!Path.IsPathRooted(app)||Path.GetFileName(app)!="StyxPreview.exe"||Hash(app)!=Hash(Path.Combine(root,"StyxPreview.exe")))throw new IOException();StartApp(app);Close();}catch{status.Text="Styx could not reopen. Open your installed Styx app manually; keep this recovery record.";}}
  [STAThread] static int Main(string[] args){bool rollback=args.Length==2&&args[0]=="--rollback";int owner=0;if(args.Length!=0&&(!rollback||!Int32.TryParse(args[1],out owner)||owner<1))return 2;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Updater(rollback,owner));return 0;}
 }
}
